/**
 * Per-slot raw-`ArmorValue`-array-position -> corrected `slots` value
 * override. Fixes the male/female armor-pair `slots`-transposition bug
 * documented in vallode/mhfu-blacksmith#30's "Update 2": raw `slots` is
 * swapped between certain paired armor pieces (e.g. "X Helm"/"X Cap") even
 * though every other stat field on both entries is correctly identified via
 * `armor-index-corrections.json`.
 *
 * Generated by `scripts/generate-armor-slots-corrections.ts` (not run at
 * pipeline runtime) — see that script's module doc comment for the full
 * pairing + verification methodology. In short: pairs are identified
 * *structurally* (already-confirmed name resolution + a known gendered-
 * piece-name-suffix match, e.g. `Helm`/`Cap`), and a correction is only
 * recorded when the pair's raw `slots` values are a **clean transposition**
 * against committed data (each side's raw value exactly equals the *other*
 * side's committed value, and the two committed values actually differ).
 * Ambiguous or partial mismatches are left uncorrected rather than guessed.
 *
 * **Known limitation**: only 8 pairs (16 items) are confirmed correctable
 * this way (6 head, 2 waist; 0 chest/arm/leg) — a small, high-confidence
 * subset of the broader, still-partly-unexplained `slots` mismatch count.
 * Most candidate gendered pairs either already have correct raw `slots`, or
 * show a non-clean mismatch (one or both sides disagree with *both* the
 * expected and swapped value) that isn't safe to auto-correct. Regenerate if
 * `armor-index-corrections.json` or `data/armor/` changes.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import type { ArmorSlot } from "../tables/armor.js";

const CORRECTIONS_PATH = path.join(path.dirname(fileURLToPath(import.meta.url)), "armor-slots-corrections.json");

let cache: Record<ArmorSlot, Record<string, number>> | null = null;

function load(): Record<ArmorSlot, Record<string, number>> {
  if (!cache) cache = JSON.parse(readFileSync(CORRECTIONS_PATH, "utf-8"));
  return cache!;
}

/**
 * Returns the corrected `slots` value for a raw `ArmorValue` array position
 * `rawIndex` in `slot`, or `rawSlots` unchanged if no correction applies
 * (the overwhelming majority of entries — this table only overrides the
 * small, confirmed-clean-transposition subset).
 */
export function correctedArmorSlots(slot: ArmorSlot, rawIndex: number, rawSlots: number): number {
  const table = load()[slot];
  if (!table) return rawSlots;
  const corrected = table[rawIndex];
  return corrected !== undefined ? corrected : rawSlots;
}
